                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    rr,cc=r+dr,c+dc
                    if 0<=rr<h and 0<=cc<w and g[rr][cc]==2 and (rr,cc) not in seen:
                        seen.add((rr,cc)); q.append((rr,cc))
            top,bottom=min(r for r,c in comp),max(r for r,c in comp)
            left,right=min(c for r,c in comp),max(c for r,c in comp)
            if bottom-top<2 or right-left<2: continue
            if all(g[top][c]==g[bottom][c]==2 for c in range(left,right+1)) and all(g[r][left]==g[r][right]==2 for r in range(top,bottom+1)):
